```tsx
import { useState } from 'react';

// ❌ WRONG — local variable approach
function WrongCounter() {
  let count = 0;  // Resets to 0 every render!
  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => { count++; }}>  {/* No re-render! */}
        Increment
      </button>
    </div>
  );
}

// ✓ CORRECT — useState approach
export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>
        Increment
      </button>
    </div>
  );
}
```

react-state-002.example:
```tsx
import { useState } from 'react';

export default function TextInput() {
  // Destructure: [current value, setter function] = useState(initial value)
  const [text, setText] = useState('');  // Starts as empty string
  const [isVisible, setIsVisible] = useState(true);  // Starts as true

  return (
    <div>
      <input
        value={text}
        onChange={(e) => setText(e.target.value)}  // Update on change
        placeholder="Type something"
      />
      <p>You typed: {text}</p>

      <button onClick={() => setIsVisible(!isVisible)}>
        Toggle visibility
      </button>
      {isVisible && <p>Visible!</p>}
    </div>
  );
}
```

